import { Match as M, Option, Schema as S } from "effect";
import { Calendar, Command, Submodel } from "foldkit";
import type { Html } from "foldkit/html";
import { html } from "foldkit/html";
import { m } from "foldkit/message";
import { evo } from "foldkit/struct";

import * as UiCalendar from "../../ui/shadcn-calendar";

// MODEL

export const Model = S.Struct({
  calendar: UiCalendar.Model,
  selectedDate: Calendar.CalendarDate,
  viewedMonth: S.String,
});

export type Model = typeof Model.Type;

// MESSAGE

export const GotCalendarMessage = m("GotCalendarMessage", {
  message: UiCalendar.Message,
});

export const Message = S.Union([GotCalendarMessage]);
export type Message = typeof Message.Type;

// INIT

const today = Calendar.make(2026, 4, 16);

const formatMonth = (date: Calendar.CalendarDate): string =>
  `${date.year}-${String(date.month).padStart(2, "0")}`;

export const init = (): readonly [
  Model,
  readonly Command.Command<Message>[],
] => [
  {
    calendar: UiCalendar.init({
      id: "shadcn-calendar-basic",
      today,
      initialSelectedDate: today,
    }),
    selectedDate: today,
    viewedMonth: formatMonth(today),
  },
  [],
];

// UPDATE

export const update = (
  model: Model,
  message: Message
): readonly [Model, readonly Command.Command<Message>[]] =>
  M.value(message).pipe(
    M.withReturnType<readonly [Model, readonly Command.Command<Message>[]]>(),
    M.tagsExhaustive({
      GotCalendarMessage: ({ message }) => {
        const [calendar, commands, maybeOutMessage] = UiCalendar.update(
          model.calendar,
          message
        );

        const nextModel = Option.match(maybeOutMessage, {
          onNone: () => evo(model, { calendar: () => calendar }),
          onSome: M.type<UiCalendar.OutMessage>().pipe(
            M.tagsExhaustive({
              ChangedViewMonth: ({ year, month }) =>
                evo(model, {
                  calendar: () => calendar,
                  viewedMonth: () =>
                    `${year}-${String(month).padStart(2, "0")}`,
                }),
              SelectedDate: ({ date }) =>
                evo(model, {
                  calendar: () => calendar,
                  selectedDate: () => date,
                }),
            })
          ),
        });

        return [
          nextModel,
          Command.mapMessages(commands, (message) =>
            GotCalendarMessage({ message })
          ),
        ];
      },
    })
  );

// VIEW

export const view = Submodel.defineView<Model, Message>((model): Html => {
  const h = html<Message>();

  return h.div(
    [h.Class("space-y-3")],
    [
      h.submodel({
        slotId: model.calendar.id,
        model: model.calendar,
        view: UiCalendar.view,
        viewInputs: {
          toView: UiCalendar.shadcnCalendarView,
        },
        toParentMessage: (message) => GotCalendarMessage({ message }),
      }),
    ]
  );
});

import { Scene } from "foldkit";
import { describe, test } from "vitest";

import * as ShadcnCalendarBasicExample from "./main";

describe("shadcn Calendar Basic example", () => {
  test("renders a real single-date calendar without local feedback text", () => {
    Scene.scene(
      {
        update: ShadcnCalendarBasicExample.update,
        view: ShadcnCalendarBasicExample.view,
      },
      Scene.with(ShadcnCalendarBasicExample.init()[0]),
      Scene.expect(
        Scene.role("button", { name: "Thursday, April 16, 2026" })
      ).toExist(),
      Scene.expect(Scene.text("Selected date: 2026-04-16")).not.toExist(),
      Scene.expect(Scene.text("Viewed month: 2026-04")).not.toExist(),
      Scene.click(Scene.role("button", { name: "Monday, April 20, 2026" })),
      Scene.click(Scene.role("button", { name: "Next month" })),
      Scene.expect(
        Scene.role("button", { name: "Friday, May 1, 2026" })
      ).toExist()
    );
  });
});
